import { styled } from '@hexa-ui/theme';

export const StyledBigNumberCenteredWrapper = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
});

export const StyledBigNumberCenteredSecondaryInfo = styled('div', {
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  paddingTop: '12px',
});

export const StyledBigNumberColumnDivider = styled('div', {
  width: '1px',
  minHeight: '100%',
  alignSelf: 'stretch',
  flexShrink: 0,
  margin: '0 8px',
  background: '#14141414',
});

export const StyledBigNumberItemContainer = styled('div', {
  display: 'flex',
  flexDirection: 'row',
  gap: '8px',

  variants: {
    orientation: {
      vertical: {},
      horizontal: {
        display: 'grid',
        gap: '80px',
      },
      center: {},
      none: {},
    },
    alignment: {
      left: {},
      center: {},
    },
  },

  compoundVariants: [
    {
      orientation: 'vertical',
      alignment: 'left',
      css: {
        justifyContent: 'space-between',
      },
    },
    {
      orientation: 'vertical',
      alignment: 'center',
      css: {
        width: '100%',
        gap: 0,
      },
    },
  ],

  defaultVariants: {
    orientation: 'vertical',
    alignment: 'left',
  },
});

export const StyledBigNumberItemContent = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',

  variants: {
    spacing: {
      loose: {
        gap: '16px',
      },
      cozy: {
        gap: '4px',
      },
    },
    alignment: {
      left: {},
      center: {
        alignItems: 'center',
        textAlign: 'center',
      },
    },
    orientation: {
      vertical: {},
      horizontal: {},
      center: {
        alignItems: 'flex-start',
      },
      none: {},
    },
  },

  compoundVariants: [
    {
      alignment: 'center',
      orientation: 'vertical',
      css: {
        flex: 1,
        minWidth: 0,
        justifyContent: 'center',
      },
    },
  ],
});

export const StyledBigNumberMainContent = styled('div', {
  display: 'flex',
  alignItems: 'center',
  gap: '4px',

  variants: {
    alignment: {
      left: {},
      center: {
        justifyContent: 'center',
      },
    },
  },

  defaultVariants: {
    alignment: 'left',
  },
});

export const StyledBigNumberComparisonContainer = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  alignItems: 'start',
  gap: '4px',

  variants: {
    preserveSpace: {
      true: {
        minWidth: '20px',
      },
      false: {},
    },
    alignment: {
      left: {},
      center: {
        alignItems: 'center',
      },
    },
  },

  defaultVariants: {
    preserveSpace: false,
    alignment: 'left',
  },
});

export const StyledBigNumberSecondaryInfoContainer = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
});

export const StyledBigNumberSecondaryInfoValue = styled('div', {
  display: 'flex',
  gap: '4px',
  alignItems: 'center',

  variants: {
    hasValue: {
      true: {
        gap: '4px',
      },
      false: {
        gap: '0px',
      },
    },
  },
});
